async function refreshMemory(){if(memoryLoading)return;memoryLoading=true;const state=$('#memory-state'),had=memoryItems.length;state.classList.remove('hidden','error');state.textContent=had?'Refreshing memories…':'Loading memories…';state.setAttribute('aria-busy','true');try{const folder=$('#memory-folder').value,data=await api('/api/memory'+(folder?'?folder_id='+Number(folder):''));if(!data||!Array.isArray(data.records))throw new ApiError('Yaad returned an incomplete memory response. Retry to reload it.',200);memoryItems=data.records;memoryPage=0;renderMemoryFolderOptions();renderMemory();state.classList.add('hidden')}catch(error){setErrorState(state,'Memories could not be loaded. Check that Yaad is running, then retry.',refreshMemory)}finally{state.removeAttribute('aria-busy');memoryLoading=false}}
function renderMemoryFolderOptions(){const select=$('#memory-folder'),old=select.value;select.innerHTML='<option value="">All folders</option>'+folders.map(f=>'<option value="'+Number(f.id)+'">'+esc(shortPath(f.path))+'</option>').join('');if(old&&[...select.options].some(o=>o.value===old))select.value=old}
function renderMemory(){const host=$('#memory-list');host.replaceChildren();$('#memory-table-wrap').classList.remove('hidden');const rows=memoryItems.filter(memoryMatchesFilter);if(!rows.length){host.innerHTML='<tr><td colspan="6" class="table-empty">'+(memoryItems.length?'No memories match this filter.':'No memories yet. Run extraction on an indexed folder to create them.')+'</td></tr>';updateMemoryPager(0);$('#memory-extract').disabled=!$('#memory-folder').value;return}if(memoryPage>=Math.max(1,Math.ceil(rows.length/10))*10)memoryPage=(Math.ceil(rows.length/10)-1)*10;rows.slice(memoryPage,memoryPage+10).forEach(r=>{const row=document.createElement('tr'),status=memoryStatusBadge(r),serving=memoryServingBadge(r);row.innerHTML='<td><button type="button" class="cell-detail memory-title" data-record="'+Number(r.id)+'" title="'+esc(r.title)+'">'+esc(r.title)+'</button></td><td>'+esc(memoryTypeLabel(r.record_type))+'</td><td class="egress-time" title="'+esc(memoryDateLabel(r))+'">'+esc(memoryDateLabel(r))+'</td><td><span class="status-badge '+status[0]+'">'+esc(status[1])+'</span></td><td><span class="status-badge '+serving[0]+'" title="'+esc(r.serving?.reason||'')+'">'+esc(serving[1])+'</span></td><td><button class="table-action memory-inspect" data-record="'+Number(r.id)+'">Inspect</button></td>';host.append(row)});host.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>openMemoryRecord(Number(b.dataset.record)));updateMemoryPager(rows.length);$('#memory-extract').disabled=!$('#memory-folder').value}
function updateMemoryPager(total){const start=total?memoryPage+1:0,end=Math.min(memoryPage+10,total);$('#memory-page-label').textContent=start+'–'+end+' of '+total;$('#memory-prev').disabled=memoryPage===0;$('#memory-next').disabled=end>=total}
function openMemoryRecord(id){const r=(memoryItems||[]).find(x=>Number(x.id)===Number(id));if(!r)return;flaggingRecordId=id;$('#memory-dialog-title').textContent=r.title;$('#memory-dialog-detail').textContent=r.detail||'No further detail recorded.';const status=memoryStatusBadge(r),serving=memoryServingBadge(r);$('#memory-dialog-badges').innerHTML='<span class="status-badge '+status[0]+'">'+esc(status[1])+'</span> <span class="status-badge '+serving[0]+'">'+esc(serving[1])+'</span> <span class="status-badge info">'+esc(memoryTypeLabel(r.record_type))+'</span>';const body=$('#memory-dialog-body');body.replaceChildren();[['Date',esc(memoryDateLabel(r))],['Assignee',esc(r.assignee||'Nobody assigned')],['Serving',esc(serving[1])+(r.serving?.reason?' — '+esc(r.serving.reason):'')],['Sources',String((r.evidence||[]).length)+' cited']].forEach(([t,v])=>{const dt=document.createElement('dt');dt.textContent=t;const dd=document.createElement('dd');dd.innerHTML=v;body.append(dt,dd)});const list=$('#memory-evidence-list');list.replaceChildren();(r.evidence||[]).forEach(ev=>{let loc={};try{loc=JSON.parse(ev.locator||'{}')}catch{};const gone=!ev.file,b=document.createElement('button');b.type='button';b.className='memory-evidence'+(gone?' gone':'');b.disabled=gone;b.setAttribute('aria-label',(gone?'Source removed, kept for history: ':'Open source: ')+(ev.excerpt||''));b.innerHTML='<span class="source-icon">'+sourceIcon(loc.type)+'</span><span class="source-name"><span class="source-filename">'+esc(gone?'Source removed · kept for history':shortPath(ev.file))+'</span><small>'+esc(((loc.type==='text_span'&&(locatorLabel(loc)===shortPath(ev.file)||locatorLabel(loc)===shortPath(ev.file).replace(/\.[A-Za-z0-9]+$/,'')))?'Text':locatorLabel(loc))+(ev.role&&ev.role!=='supports'?' · '+ev.role:''))+'</small></span><span class="memory-excerpt">'+esc(ev.excerpt||'')+'</span>';if(!gone)b.onclick=()=>openEvidence(ev.evidence_id);list.append(b)});if(!(r.evidence||[]).length){const p=document.createElement('p');p.className='table-empty';p.textContent='No evidence rows stored.';list.append(p)}$('#memory-dialog').showModal()}
function openMemoryReport(){if(!flaggingRecordId)return;$('#memory-report-reason').value='';$('#memory-report-result').textContent='';$('#memory-report-dialog').showModal();$('#memory-report-reason').focus()}
async function submitMemoryReport(event){event.preventDefault();if(!flaggingRecordId)return;const reason=$('#memory-report-reason').value.trim(),out=$('#memory-report-result');if(!reason){out.textContent='Describe the problem first.';return}out.textContent='Sending report…';try{await api('/api/memory/'+flaggingRecordId+'/flag',{reason});out.textContent='Report recorded. Thank you.';setTimeout(()=>{if($('#memory-report-dialog').open)$('#memory-report-dialog').close()},1200)}catch(error){out.textContent=error.message}}
async function runMemoryExtract(){const folder=$('#memory-folder').value,button=$('#memory-extract'),out=$('#memory-extract-result');if(!folder||button.disabled)return;button.disabled=true;button.dataset.busy='true';out.textContent='Extraction is running…';try{const s=await api('/api/memory/extract',{folder_id:Number(folder)},{timeoutMs:300000});out.textContent='Finished: '+s.accepted+' of '+s.returned+' accepted, '+(s.rejected||[]).length+' rejected, '+s.conflicts.length+' conflicts, '+s.stale.length+' stale, $'+Number(s.spend_usd||0).toFixed(4)+' spent.';await refreshMemory()}catch(error){out.textContent=error.message}finally{delete button.dataset.busy;button.disabled=!$('#memory-folder').value}}
function renderThemeButtons(){const theme=document.documentElement.dataset.theme||'medium';document.querySelectorAll('[data-theme-choice]').forEach(button=>{const active=button.dataset.themeChoice===theme;button.classList.toggle('selected',active);button.setAttribute('aria-pressed',String(active))})}
function applyTheme(theme,persist=true){if(!['light','medium','dark'].includes(theme))theme='medium';document.documentElement.dataset.theme=theme;if(persist){try{localStorage.setItem(THEME_STORE,theme)}catch{}}renderThemeButtons()}
function resizeComposer(){const box=$('#question');box.style.height='auto';box.style.height=Math.min(box.scrollHeight,150)+'px';$('#send-button').disabled=!box.value.trim()||Boolean($('#ask-form').dataset.busy)}
$('#question').addEventListener('input',resizeComposer);$('#question').addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();$('#ask-form').requestSubmit()}});
$('#ask-form').addEventListener('submit',async event=>{event.preventDefault();const box=$('#question'),question=box.value.trim();if(!question||$('#ask-form').dataset.busy)return;let item=current();if(!item){item={id:crypto.randomUUID(),title:question.length>38?question.slice(0,35)+'…':question,messages:[]};conversations.unshift(item);activeId=item.id}const edit=editingQuestion&&editingQuestion.conversationId===item.id?editingQuestion:null;if(edit){item.messages[edit.index].text=question;item.messages.splice(edit.index+1);editingQuestion=null}else item.messages.push({role:'user',text:question});item.messages.push({role:'assistant',pending:true});saveConversations();renderConversation({scroll:edit?'preserve':'bottom'});renderRecents();box.value='';resizeComposer();$('#ask-form').dataset.busy='true';$('#send-button').disabled=true;try{const folderValue=$('#folder-scope').value,result=await api('/api/ask',{question,folder_id:folderValue?Number(folderValue):null},{timeoutMs:120000});item.messages[item.messages.length-1]={role:'assistant',result};saveConversations();renderConversation({scroll:$('#conversation-scroll').scrollHeight-$('#conversation-scroll').scrollTop-$('#conversation-scroll').clientHeight<100?'bottom':'preserve'})}catch(error){item.messages[item.messages.length-1]={role:'assistant',result:{status:'error',answer:error.message,evidence:[]}};saveConversations();renderConversation({scroll:$('#conversation-scroll').scrollHeight-$('#conversation-scroll').scrollTop-$('#conversation-scroll').clientHeight<100?'bottom':'preserve'})}finally{delete $('#ask-form').dataset.busy;resizeComposer()}});
$('#folder-form').addEventListener('submit',async event=>{event.preventDefault();const button=$('#folder-add'),message=$('#folder-result');button.disabled=true;button.querySelector('span').textContent='Opening Finder…';message.textContent='';try{const result=await api('/api/folders/pick',{cloud_consent:$('#cloud-consent').checked},{timeoutMs:185000});if(result.cancelled)return;message.textContent=(result.already_added?'Folder was already in your library. ':'Folder added: ')+result.path+'. Cloud consent is '+(result.cloud_consent?'on':'off')+'.';selectedFolderId=result.folder_id;await refreshStatus();$('#folder-scope').value=String(selectedFolderId);updatePrivacyStatus()}catch(error){message.textContent=error.status===400||error.status===422?'Couldn’t add that folder. Choose a folder you have permission to open.':error.status===501?'The native folder chooser is unavailable. Run Yaad in the desktop app.':error.message}finally{button.disabled=false;button.querySelector('span').textContent='Choose folder'}});
$('#folder-scope').onchange=()=>{selectedFolderId=$('#folder-scope').value||null;selectFolder(selectedFolderId)};$('#cloud-consent').onchange=async()=>{if(!selectedFolderId){$('#folder-result').textContent='Choose a folder before changing its cloud consent.';$('#cloud-consent').checked=false;return}const box=$('#cloud-consent'),previous=!box.checked;box.disabled=true;try{await api('/api/folders/'+Number(selectedFolderId)+'/consent',{cloud_consent:box.checked});await refreshStatus();$('#folder-result').textContent='Folder consent updated. Reindex this folder to retry eligible files.'}catch(error){box.checked=previous;$('#folder-result').textContent=error.message}finally{box.disabled=false}};$('#consent-info').onclick=()=>$('#consent-dialog').showModal();$('#consent-close').onclick=$('#consent-done').onclick=()=>$('#consent-dialog').close();
