;
$('#memory-prev').onclick=()=>{if(memoryPage>=10){memoryPage-=10;renderMemory()}};$('#memory-next').onclick=()=>{memoryPage+=10;renderMemory()};$('#memory-filter').onchange=()=>{memoryPage=0;renderMemory()};$('#memory-folder').onchange=()=>{memoryPage=0;$('#memory-extract').disabled=!$('#memory-folder').value;refreshMemory()};$('#memory-refresh').onclick=()=>{memoryPage=0;refreshMemory()};$('#memory-extract').onclick=runMemoryExtract;$('#memory-report-open').onclick=openMemoryReport;$('#memory-report-form').onsubmit=submitMemoryReport;$('#memory-report-close').onclick=$('#memory-report-cancel').onclick=()=>$('#memory-report-dialog').close();$('#memory-dialog-close').onclick=$('#memory-dialog-done').onclick=()=>$('#memory-dialog').close();
